Interface sketch (TypeScript-ish):

export interface ForecastProvider {
  getForecast(ctx: Context, req: ForecastRequest): Promise<ForecastResponse>;
}

export type ForecastResponse = {
  generatedAt: number; // unix ms
  source: 'forecast-service' | 'static-schedule' | 'none';
  confidence?: number;
  points: Array<{ ts: number; rps: number }>;
};

Validation behavior:
- reject if Date.now() - generatedAt > maxForecastAgeMs
- reject if points.length == 0
- reject if last(points).ts < now - maxPointAgeMs
- on reject => prediction unavailable => reactive-only path
